/**
 * 考试 WebSocket composable
 *
 * 负责与后端 /ws/exam/{examId}?token=xxx 的全部业务交互：
 * - 连接建立后每 30s 发送 heartbeat（携带剩余秒数）
 * - 处理 time-sync（服务器时间 / 剩余秒数同步）
 * - 处理 heartbeat-ack（服务器时间回写）
 * - 处理 save-ack（答案保存确认）
 * - 处理 submit-result（交卷结果）
 * - 处理 force-submit（考试时间到，强制交卷）
 *
 * 提供响应式状态：connected / status / serverTime / remainingSeconds / lastResult / lastError
 * 暴露方法：connect(examId) / disconnect() / sendHeartbeat(remaining) /
 *           sendAnswer(questionId, answer, remaining) / submit(remaining)
 *
 * 说明：传输层保活 ping 由 WebSocketManager 内部每 30s 发送，与本 composable
 *      的业务 heartbeat 互不干扰——前者是连接探活，后者携带剩余时长上报。
 */
import { onBeforeUnmount, ref } from 'vue'
import { WebSocketManager } from '@/utils/websocket'

/** 交卷结果（对应后端 submit-result 消息） */
export interface ExamSubmitResult {
  examId: number
  totalScore: number
  scorePercentage: number
  correctCount: number
  wrongCount: number
}

/** 连接状态机 */
export type ExamWsStatus = 'closed' | 'connecting' | 'open'

type ForceSubmitHandler = (reason: string) => void
type SubmitResultHandler = (result: ExamSubmitResult) => void
type SaveAckHandler = (questionId: number) => void

/** 业务心跳间隔（ms），与后端约定 30s */
const HEARTBEAT_INTERVAL = 30_000
/** submit 后等待 submit-result 的超时（ms） */
const SUBMIT_TIMEOUT = 15_000

interface PendingSubmit {
  resolve: (r: ExamSubmitResult) => void
  reject: (e: Error) => void
  timer: number | null
}

export function useExamWebSocket() {
  /** 是否已连接（OPEN） */
  const connected = ref(false)
  /** 三态连接状态，便于 UI 展示「连接中」 */
  const status = ref<ExamWsStatus>('closed')
  /** 服务器时间（ISO 字符串），由 time-sync / heartbeat-ack 更新 */
  const serverTime = ref('')
  /** 剩余秒数：由组件 onTick 写入（客户端倒计时口径），time-sync 也会回写校准 */
  const remainingSeconds = ref(0)
  /** 最近一次交卷结果 */
  const lastResult = ref<ExamSubmitResult | null>(null)
  /** 最近一次错误信息（传输错误或后端 error 消息） */
  const lastError = ref('')

  let ws: WebSocketManager | null = null
  let heartbeatTimer: number | null = null
  /** 事件取消注册函数集合，disconnect 时统一清理 */
  const cleanups: Array<() => void> = []

  const forceSubmitHandlers = new Set<ForceSubmitHandler>()
  const submitResultHandlers = new Set<SubmitResultHandler>()
  const saveAckHandlers = new Set<SaveAckHandler>()

  /** 待 resolve 的 submit Promise；同一时刻只允许一个 */
  let pendingSubmit: PendingSubmit | null = null

  /* ---------------- 业务心跳 ---------------- */

  const startHeartbeat = () => {
    stopHeartbeat()
    heartbeatTimer = window.setInterval(() => {
      sendHeartbeat(remainingSeconds.value)
    }, HEARTBEAT_INTERVAL)
  }

  const stopHeartbeat = () => {
    if (heartbeatTimer !== null) {
      clearInterval(heartbeatTimer)
      heartbeatTimer = null
    }
  }

  /* ---------------- 连接 ---------------- */

  const connect = (examId: number | string) => {
    // 已存在则先彻底断开（含清理事件），避免重复绑定
    disconnect()

    const token = localStorage.getItem('token')
    if (!token) {
      lastError.value = '未登录，无法建立考试 WebSocket'
      status.value = 'closed'
      connected.value = false
      return
    }

    status.value = 'connecting'
    ws = new WebSocketManager({
      path: `/ws/exam/${examId}`,
      autoReconnect: true,
      heartbeatInterval: HEARTBEAT_INTERVAL,
    })

    cleanups.push(
      ws.on('open', () => {
        connected.value = true
        status.value = 'open'
        lastError.value = ''
        startHeartbeat()
      }),
    )

    cleanups.push(
      ws.on('close', () => {
        connected.value = false
        status.value = 'closed'
        stopHeartbeat()
      }),
    )

    cleanups.push(
      ws.on('error', (e: any) => {
        // 传输错误与后端 { type: 'error', message } 都走这里
        const msg =
          (e && typeof e === 'object' && (e.message || e.reason)) ||
          (typeof e === 'string' && e) ||
          'websocket error'
        lastError.value = String(msg)
      }),
    )

    // 服务器时间 / 剩余秒数同步
    cleanups.push(
      ws.on('time-sync', (data: any) => {
        if (data?.serverTime) serverTime.value = data.serverTime
        if (typeof data?.remainingSeconds === 'number') {
          remainingSeconds.value = data.remainingSeconds
        }
      }),
    )

    // 心跳确认：回写服务器时间
    cleanups.push(
      ws.on('heartbeat-ack', (data: any) => {
        if (data?.serverTime) serverTime.value = data.serverTime
      }),
    )

    // 答案保存确认
    cleanups.push(
      ws.on('save-ack', (data: any) => {
        if (typeof data?.questionId === 'number') {
          saveAckHandlers.forEach((h) => {
            try {
              h(data.questionId)
            } catch {
              /* ignore */
            }
          })
        }
      }),
    )

    // 交卷结果
    cleanups.push(
      ws.on('submit-result', (data: any) => {
        const result = data as ExamSubmitResult
        lastResult.value = result
        submitResultHandlers.forEach((h) => {
          try {
            h(result)
          } catch {
            /* ignore */
          }
        })
        if (pendingSubmit) {
          if (pendingSubmit.timer !== null) clearTimeout(pendingSubmit.timer)
          pendingSubmit.resolve(result)
          pendingSubmit = null
        }
      }),
    )

    // 强制交卷
    cleanups.push(
      ws.on('force-submit', (data: any) => {
        const reason = (data?.reason as string) || '考试时间已到'
        forceSubmitHandlers.forEach((h) => {
          try {
            h(reason)
          } catch {
            /* ignore */
          }
        })
      }),
    )

    ws.connect()
  }

  const disconnect = () => {
    stopHeartbeat()
    // 放弃尚未回包的 submit
    if (pendingSubmit) {
      if (pendingSubmit.timer !== null) clearTimeout(pendingSubmit.timer)
      pendingSubmit.reject(new Error('websocket closed before submit-result'))
      pendingSubmit = null
    }
    // 清理所有事件绑定
    cleanups.splice(0).forEach((fn) => fn())
    if (ws) {
      ws.disconnect()
      ws = null
    }
    connected.value = false
    status.value = 'closed'
  }

  /* ---------------- 主动发送 ---------------- */

  /** 发送业务心跳（携带剩余秒数） */
  const sendHeartbeat = (remaining: number) => {
    ws?.send({
      type: 'heartbeat',
      remainingSeconds: Math.max(0, Math.floor(remaining)),
    })
  }

  /**
   * 发送单题答案。
   * @returns 是否成功投递；保存确认通过 onSaveAck 回调或 save-ack 事件获取
   */
  const sendAnswer = (
    questionId: number,
    userAnswer: string,
    remaining: number,
  ): boolean => {
    if (!ws) return false
    return ws.send({
      type: 'save-answer',
      questionId,
      userAnswer,
      remainingSeconds: Math.max(0, Math.floor(remaining)),
    })
  }

  /**
   * 发起交卷。返回一个 Promise：
   * - 收到 submit-result 时 resolve(result)
   * - 收到 error / 超时 / 连接断开 时 reject
   * 仅在已连接时可用；未连接请走 HTTP 兜底。
   */
  const submit = (remaining: number = 0): Promise<ExamSubmitResult> => {
    return new Promise<ExamSubmitResult>((resolve, reject) => {
      if (!ws || !ws.isConnected) {
        reject(new Error('websocket not connected'))
        return
      }
      // 取代上一个未完成的 submit
      if (pendingSubmit) {
        if (pendingSubmit.timer !== null) clearTimeout(pendingSubmit.timer)
        pendingSubmit.reject(new Error('superseded by a new submit'))
        pendingSubmit = null
      }
      pendingSubmit = {
        resolve,
        reject,
        timer: window.setTimeout(() => {
          if (pendingSubmit) {
            pendingSubmit.reject(new Error('submit-result timeout'))
            pendingSubmit = null
          }
        }, SUBMIT_TIMEOUT),
      }
      ws.send({
        type: 'submit',
        remainingSeconds: Math.max(0, Math.floor(remaining)),
      })
    })
  }

  /* ---------------- 事件订阅 ---------------- */

  /** 注册强制交卷回调，返回取消函数 */
  const onForceSubmit = (cb: ForceSubmitHandler): (() => void) => {
    forceSubmitHandlers.add(cb)
    return () => forceSubmitHandlers.delete(cb)
  }

  /** 注册交卷结果回调，返回取消函数 */
  const onSubmitResult = (cb: SubmitResultHandler): (() => void) => {
    submitResultHandlers.add(cb)
    return () => submitResultHandlers.delete(cb)
  }

  /** 注册答案保存确认回调，返回取消函数 */
  const onSaveAck = (cb: SaveAckHandler): (() => void) => {
    saveAckHandlers.add(cb)
    return () => saveAckHandlers.delete(cb)
  }

  // 组件卸载时自动断开（幂等）
  onBeforeUnmount(() => disconnect())

  return {
    // 响应式状态
    connected,
    status,
    serverTime,
    remainingSeconds,
    lastResult,
    lastError,
    // 连接管理
    connect,
    disconnect,
    // 主动发送
    sendHeartbeat,
    sendAnswer,
    submit,
    // 事件订阅
    onForceSubmit,
    onSubmitResult,
    onSaveAck,
  }
}

export type UseExamWebSocketReturn = ReturnType<typeof useExamWebSocket>

/**
 * 通知 WebSocket composable
 *
 * 负责与后端 /ws/notifications?token=xxx（该端点后端将补充）的交互：
 * - 监听实时消息推送，新消息到达时弹出 ElNotification
 * - 响应式维护未读数 unreadCount
 * - 断线自动重连（由 WebSocketManager 负责）
 *
 * 状态采用模块级单例：多处调用 useNotificationWebSocket() 共享同一连接与
 * 同一份未读数，便于在 App.vue 连接、在 Header.vue 消费。
 */
import { ref } from 'vue'
import { ElNotification } from 'element-plus'
import { WebSocketManager } from '@/utils/websocket'
import type { MessageNotification } from '@/types/notification'

/* ---------------- 模块级单例状态 ---------------- */

const connected = ref(false)
const unreadCount = ref(0)
const lastMessage = ref<MessageNotification | null>(null)
const lastError = ref('')

let ws: WebSocketManager | null = null
const cleanups: Array<() => void> = []
const messageHandlers = new Set<(m: MessageNotification) => void>()

/** 后端可能使用的推送 type 集合，命中任一即按消息处理 */
const MESSAGE_TYPES = ['notification', 'new-message', 'message', 'notify'] as const

/* ---------------- 工具方法 ---------------- */

/**
 * 从任意结构的推送体里提取消息对象。
 * 兼容 { type, payload } / { type, data } / { type, message } / 裸消息等形态。
 */
function extractNotification(raw: any): MessageNotification | null {
  if (!raw || typeof raw !== 'object') return null
  const candidates = [raw.payload, raw.data, raw.message, raw.notification]
  for (const c of candidates) {
    if (c && typeof c === 'object' && (c.title !== undefined || c.id !== undefined)) {
      return c as MessageNotification
    }
  }
  // 本身就是消息体
  if (raw.title !== undefined || raw.id !== undefined) {
    return raw as MessageNotification
  }
  return null
}

/** 按优先级 / 分类决定 ElNotification 的 type */
function resolveNotificationType(msg: MessageNotification): 'success' | 'warning' | 'error' | 'info' {
  if (msg.priority === 2) return 'error'
  if (msg.category === 'ALERT') return 'warning'
  if (msg.category === 'ACHIEVEMENT') return 'success'
  return 'info'
}

/** 弹出一条桌面通知 */
function showNotification(msg: MessageNotification) {
  ElNotification({
    title: msg.title || msg.typeLabel || '新消息',
    message: msg.summary || (msg.content ? msg.content.substring(0, 80) : ''),
    type: resolveNotificationType(msg),
    duration: 5000,
    position: 'top-right',
  })
}

/** 处理一条入站消息 */
function handleIncoming(raw: any) {
  const msg = extractNotification(raw)
  if (!msg) return
  lastMessage.value = msg
  unreadCount.value += 1
  messageHandlers.forEach((h) => {
    try {
      h(msg)
    } catch {
      /* ignore */
    }
  })
  showNotification(msg)
}

/* ---------------- composable ---------------- */

export function useNotificationWebSocket() {
  const connect = () => {
    const token = localStorage.getItem('token')
    if (!token) return
    // 已连接则不重复建链
    if (ws && ws.isConnected) return

    // 清理可能存在的旧实例（保留 unreadCount / lastMessage 业务态）
    if (ws) {
      ws.disconnect()
      cleanups.splice(0).forEach((fn) => fn())
      ws = null
    }
    connected.value = false

    ws = new WebSocketManager({
      path: '/ws/notifications',
      autoReconnect: true,
      heartbeatInterval: 30_000,
    })

    cleanups.push(
      ws.on('open', () => {
        connected.value = true
        lastError.value = ''
      }),
    )

    cleanups.push(
      ws.on('close', () => {
        connected.value = false
      }),
    )

    cleanups.push(
      ws.on('error', (e: any) => {
        const msg =
          (e && typeof e === 'object' && (e.message || e.reason)) ||
          (typeof e === 'string' && e) ||
          'websocket error'
        lastError.value = String(msg)
      }),
    )

    // 兼容多种推送 type
    MESSAGE_TYPES.forEach((t) => {
      cleanups.push(
        ws!.on(t, (data: any) => handleIncoming(data)),
      )
    })

    // 未读数同步（后端可能下发 { type: 'unread-count', total } ）
    cleanups.push(
      ws.on('unread-count', (data: any) => {
        if (data && typeof data.total === 'number') unreadCount.value = data.total
        else if (data && typeof data.count === 'number') unreadCount.value = data.count
      }),
    )

    ws.connect()
  }

  const disconnect = () => {
    cleanups.splice(0).forEach((fn) => fn())
    if (ws) {
      ws.disconnect()
      ws = null
    }
    connected.value = false
  }

  /** 订阅新消息，返回取消函数 */
  const onMessage = (cb: (m: MessageNotification) => void): (() => void) => {
    messageHandlers.add(cb)
    return () => messageHandlers.delete(cb)
  }

  /** 本地标记全部已读 */
  const markAllRead = () => {
    unreadCount.value = 0
  }

  /** 未读数减 n（点击单条后调用） */
  const decrementUnread = (n: number = 1) => {
    unreadCount.value = Math.max(0, unreadCount.value - n)
  }

  /** 用 HTTP 拉取的真实值校准未读数 */
  const setUnreadCount = (n: number) => {
    unreadCount.value = Math.max(0, Math.floor(n))
  }

  return {
    // 响应式状态
    connected,
    unreadCount,
    lastMessage,
    lastError,
    // 连接管理
    connect,
    disconnect,
    // 订阅 / 状态维护
    onMessage,
    markAllRead,
    decrementUnread,
    setUnreadCount,
  }
}

export type UseNotificationWebSocketReturn = ReturnType<typeof useNotificationWebSocket>

import { createRouter, createWebHashHistory } from 'vue-router'
import type { RouteRecordRaw } from 'vue-router'
import { useAuthStore, HOME_BY_ROLE } from '@/stores/auth'
import { usePermissionStore } from '@/stores/permission'
import { DISABLED_PATHS } from '@/router/asyncRoutes'
import type { Role } from '@/types/common'

/** 白名单：无需登录 */
const WHITE_LIST = ['/login', '/register']

/** 基础静态路由 */
export const constantRoutes: RouteRecordRaw[] = [
  {
    // 登录页
    // 支持三种进入方式：
    //   /login                  → 通用登录（用户在页面上选身份）
    //   /login/student          → 学生入口（页面预选、锁定 STUDENT）
    //   /login/admin            → 管理员入口
    // 也兼容 query：/login?role=student
    path: '/login/:role?',
    name: 'Login',
    component: () => import('@/views/login/index.vue'),
    meta: { title: '登录', noAuth: true },
  },
  {
    path: '/register',
    name: 'Register',
    component: () => import('@/views/register/index.vue'),
    meta: { title: '注册', noAuth: true },
  },
  {
    path: '/',
    name: 'Root',
    component: () => import('@/views/layout/index.vue'),
    children: [
      {
        path: 'redirect',
        name: 'Redirect',
        component: () => import('@/views/redirect/index.vue'),
        meta: { hidden: true },
      },
    ],
  },
  {
    path: '/:pathMatch(.*)*',
    name: 'NotFound',
    component: () => import('@/views/error/404.vue'),
    // 注意：不要给 noAuth: true。
    // 否则刷新动态路由（如 /dashboard）时，由于路由未注册会先命中此 catch-all，
    // to.meta.noAuth 继承为 true，导致守卫误判为白名单直接放行，
    // 跳过了动态路由生成逻辑，页面就永远卡在 404。
    meta: { title: '404' },
  },
]

const router = createRouter({
  history: createWebHashHistory(),
  routes: constantRoutes,
})

/**
 * 全局路由守卫 —— Vue Router 4 推荐返回值模式：
 *   - return true / undefined  → 放行
 *   - return 路径字符串或对象    → 重定向
 *   - return false             → 取消导航
 *
 * 动态路由异步生成逻辑：
 *   首次进入时根据 role 过滤 asyncRoutes → addRoute('Root', ...) → return to.fullPath 重试
 *   第二次进入时路由已就绪，直接放行
 */
router.beforeEach(async (to) => {
  const authStore = useAuthStore()
  const permissionStore = usePermissionStore()

  if (to.meta.title) {
    document.title = `${to.meta.title} - GramEval`
  }

  // 判断是否是登录路径（/login、/login/student、/login/admin）
  const isLoginRoute = to.path === '/login' || to.path.startsWith('/login/')
  const isWhitelisted = isLoginRoute || WHITE_LIST.includes(to.path) || to.meta.noAuth

  // ==================== 白名单放行 ====================
  if (isWhitelisted) {
    // 已登录用户访问登录页 → 直接跳角色首页
    if (isLoginRoute && authStore.token && authStore.role) {
      return authStore.homePath
    }
    return true
  }

  // ==================== 未登录 → 登录页 ====================
  if (!authStore.token) {
    return { path: '/login', query: { redirect: to.fullPath } }
  }

  // ==================== 有 token 但无 role（异常）→ 清空重新登录 ====================
  if (!authStore.role) {
    authStore.logout()
    return { path: '/login', query: { redirect: to.fullPath } }
  }

  // ==================== 动态路由生成 ====================
  if (!permissionStore.generated) {
    // [2026-09-26 修改] 传入超管标记：教师/老师/管理员同一角色，仅 admin 账号多 4 个管理菜单（06 §9.1）
    const accessed = permissionStore.generateRoutes(authStore.role as Role, authStore.isSuperAdmin)
    accessed.forEach((r) => {
      router.addRoute('Root', r)
    })

    const homePath = HOME_BY_ROLE[authStore.role as Role]

    // 访问根路径 → 重定向到角色首页
    if (to.path === '/' || to.path === '/redirect') {
      return { path: homePath, replace: true }
    }

    // 🔑 关键：返回 to.fullPath 字符串触发一次全新导航，
    // 让 Vue Router 用已注册的动态路由重新匹配 /dashboard 等路径。
    // 不要 return { ...to, replace: true }——to 里带着 name: 'NotFound'、
    // matched 等字段，spread 出来会让新导航继续按 NotFound 走，仍然 404。
    return to.fullPath
  }

  // ==================== 已禁用模块拦截 ====================
  // 这些模块的路由被 meta.disabled 过滤掉、不会注册（访问时命中 catch-all 即 404）。
  // 此处再拦一道，防止将来误把路由加回后仍能通过 URL 直达。
  if (DISABLED_PATHS.includes(to.path)) {
    return { path: '/404', replace: true }
  }

  // ==================== 放行 ====================
  return true
})

export default router

import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import { login as loginApi, register as registerApi, getMe } from '@/api/auth'
import type { LoginForm, RegisterForm, UserInfo, UserDetail } from '@/types/user'
import type { Role } from '@/types/common'

// [2026-09-26 修改] 登录态存储 localStorage → sessionStorage（依据 05 决策 D12 第 4 条）
//   答辩演示需要同时开多个浏览器窗口（如管理员 + 学生各一），localStorage 是多窗口共享的，
//   后登录的窗口会覆盖前一个，导致演示串号；sessionStorage 按标签页隔离，正好满足需求。
//   行为差异：① F5 刷新仍保持登录（同标签页内）② 关标签页即登出 ③ 用链接/window.open 打开的
//   新标签页会复制一份 sessionStorage 初值，演示时请手动新开窗口（Ctrl+N）。
const TOKEN_KEY = 'token'
const USER_KEY = 'userInfo'
const ROLE_KEY = 'role'

function readUser(): UserInfo | null {
  const raw = sessionStorage.getItem(USER_KEY)
  if (!raw) return null
  try {
    return JSON.parse(raw) as UserInfo
  } catch {
    return null
  }
}

/** 角色 → 首页 */
export const HOME_BY_ROLE: Record<Role, string> = {
  ADMIN: '/dashboard',
  STUDENT: '/student/home',
}

export const useAuthStore = defineStore('auth', () => {
  const token = ref<string>(sessionStorage.getItem(TOKEN_KEY) || '')
  const userInfo = ref<UserInfo | null>(readUser())
  /** 完整用户资料（GET /auth/me 拉回） */
  const userDetail = ref<UserDetail | null>(null)

  const role = computed<Role | ''>(() => {
    if (userInfo.value?.role) return userInfo.value.role
    return (sessionStorage.getItem(ROLE_KEY) as Role) || ''
  })

  const isLoggedIn = computed(() => Boolean(token.value))
  const homePath = computed<string>(() => (role.value ? HOME_BY_ROLE[role.value as Role] : '/login'))

  const login = async (form: LoginForm) => {
    const res = await loginApi(form)
    const payload = res as unknown as { data: { token: string; user: UserInfo } }
    const { token: tk, user } = payload.data

    token.value = tk
    userInfo.value = user
    sessionStorage.setItem(TOKEN_KEY, tk)
    // 头像 base64 可能很长（几十 KB），
    // sessionStorage 通常只有 5MB 且存太多 base64 拖慢序列化。
    // 这里只存轻量身份字段，avatar 需要时从 /auth/me 拉。
    sessionStorage.setItem(USER_KEY, JSON.stringify({
      id: user.id,
      username: user.username,
      displayName: user.displayName,
      role: user.role,
      // [2026-09-26 新增] 超管标记（仅 admin 账号为 true）→ 用于前端菜单分流（06 §9.1）
      superAdmin: (user as unknown as { superAdmin?: boolean }).superAdmin === true,
    }))
    sessionStorage.setItem(ROLE_KEY, user.role)
    return user
  }

  // [2026-09-26 新增] 是否超管账号：教师/老师/管理员是同一角色，
  //   仅 admin 账号额外可见「系统配置 / 操作日志 / 用户管理 / 班级管理」4 个菜单（06 §9.1）
  const isSuperAdmin = computed<boolean>(
    () => (userInfo.value as unknown as { superAdmin?: boolean } | null)?.superAdmin === true,
  )

  const register = async (form: RegisterForm) => registerApi(form)

  /** 拉当前用户完整资料 */
  const fetchMe = async () => {
    const res = await getMe()
    userDetail.value = res.data
    // 顺带同步 userInfo（displayName 若为空可用 realName 兜底）
    if (userInfo.value && res.data.realName) {
      userInfo.value = {
        ...userInfo.value,
        displayName: res.data.realName || userInfo.value.displayName,
      }
      sessionStorage.setItem(USER_KEY, JSON.stringify(userInfo.value))
    }
    return res.data
  }

  const logout = () => {
    token.value = ''
    userInfo.value = null
    userDetail.value = null
    sessionStorage.removeItem(TOKEN_KEY)
    sessionStorage.removeItem(USER_KEY)
    sessionStorage.removeItem(ROLE_KEY)
  }

  return {
    token,
    userInfo,
    userDetail,
    role,
    isLoggedIn,
    homePath,
    isSuperAdmin,
    login,
    register,
    fetchMe,
    logout,
  }
})

import { defineStore } from 'pinia'
import { ref } from 'vue'
import type { DictItem } from '@/types/common'
import { getAllDict, type DictType } from '@/api/dict'

/**
 * 字典 store —— 应用启动时拉取一次，全局缓存
 * 各页面下拉框、状态标签直接从这里读
 */
export const useDictStore = defineStore('dict', () => {
  const loaded = ref(false)
  const loading = ref(false)
  const dict = ref<Partial<Record<DictType, DictItem[]>>>({})

  const load = async (force = false) => {
    if (loaded.value && !force) return
    if (loading.value) return
    loading.value = true
    try {
      const res = await getAllDict()
      dict.value = res.data as Partial<Record<DictType, DictItem[]>>
      loaded.value = true
    } catch {
      // 静默失败，避免影响页面加载
    } finally {
      loading.value = false
    }
  }

  /** 拿指定字典（未加载则返回空数组） */
  const getItems = (type: DictType): DictItem[] => dict.value[type] || []

  /** value → label */
  const getLabel = (type: DictType, value: string | number): string => {
    const item = getItems(type).find((d) => String(d.value) === String(value))
    return item?.label ?? String(value)
  }

  return { loaded, loading, dict, load, getItems, getLabel }
})

import axios, { type AxiosRequestConfig } from 'axios'
import { ElMessage } from 'element-plus'
import router from '@/router'

/** 请求体最大字节数(3 MB),超过就本地拦截,不占带宽 */
const MAX_REQUEST_BYTES = 3 * 1024 * 1024

/** GET query string 最大长度(URL 太长后端 tomcat 会报 400) */
const MAX_QUERY_LEN = 8000

/**
 * 全局 GET 查询字符串参数上限(单字段值)。
 * 前端应通过 formLimits.ts + el-input 的 maxlength 提前把关,
 * 但如果绕过表单直接构造调用,这里再兜一层。
 */
const MAX_STRING_PARAM_LEN = 2000

const request = axios.create({
  baseURL: '/api',
  timeout: 20000,
})

/**
 * 计算大致的请求体字节数。
 * 只是估算,不追求精确 —— 只要能拦住 "上传了一个 10MB base64 图" 就够了。
 */
function estimateBytes(data: unknown): number {
  if (data == null) return 0
  if (typeof data === 'string') return data.length * 2 // UTF-16
  if (data instanceof FormData || data instanceof Blob) {
    return data instanceof Blob ? data.size : 0 // FormData 内 Blob 由浏览器估算
  }
  try {
    return JSON.stringify(data).length * 2
  } catch {
    return 0
  }
}

/** 检查 GET 参数,截断超长字符串并给出提示(避免直接 400) */
function sanitizeParams(params: Record<string, unknown> | undefined): Record<string, unknown> | undefined {
  if (!params) return params
  const out: Record<string, unknown> = {}
  for (const [k, v] of Object.entries(params)) {
    if (typeof v === 'string' && v.length > MAX_STRING_PARAM_LEN) {
      ElMessage.warning(`参数 ${k} 过长,已截断到 ${MAX_STRING_PARAM_LEN} 字符`)
      out[k] = v.slice(0, MAX_STRING_PARAM_LEN)
    } else {
      out[k] = v
    }
  }
  return out
}

// Request interceptor
request.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('token')
    if (token) {
      config.headers.Authorization = `Bearer ${token}`
    }

    // 前置校验:请求体大小
    const bytes = estimateBytes(config.data)
    if (bytes > MAX_REQUEST_BYTES) {
      ElMessage.error(`请求内容过大 (${(bytes / 1024 / 1024).toFixed(1)}MB),请精简后重试`)
      return Promise.reject(new Error('request body too large'))
    }

    // GET 参数清理
    if (config.params && typeof config.params === 'object') {
      config.params = sanitizeParams(config.params as Record<string, unknown>)
    }

    // URL 长度兜底
    if (config.url && config.url.length > MAX_QUERY_LEN) {
      ElMessage.error('请求 URL 过长')
      return Promise.reject(new Error('url too long'))
    }

    return config
  },
  (error) => Promise.reject(error)
)

// Response interceptor
request.interceptors.response.use(
  (response) => {
    // blob(文件流)不走业务错误判断
    if (
      response.request?.responseType === 'blob' ||
      response.config?.responseType === 'blob'
    ) {
      return response
    }
    const res = response.data
    if (res && res.code !== undefined && res.code !== 200) {
      ElMessage.error(res.message || 'Request failed')
      if (res.code === 401) {
        localStorage.removeItem('token')
        localStorage.removeItem('role')
        router.push('/login')
      }
      return Promise.reject(new Error(res.message || 'Request failed'))
    }
    return res
  },
  (error) => {
    const status = error.response?.status
    const backendMsg = error.response?.data?.message

    if (status === 401) {
      localStorage.removeItem('token')
      localStorage.removeItem('role')
      router.push('/login')
      ElMessage.error(backendMsg || '登录已过期,请重新登录')
    } else if (status === 403) {
      ElMessage.error(backendMsg || '没有权限访问此资源')
    } else if (status === 404) {
      ElMessage.error(backendMsg || '资源不存在')
    } else if (status === 413) {
      ElMessage.error('请求内容过大,已被服务器拒绝')
    } else if (status === 422 || status === 400) {
      ElMessage.error(backendMsg || '请求参数校验失败')
    } else if (status && status >= 500) {
      ElMessage.error(backendMsg || '服务器内部错误')
    } else if (error.code === 'ECONNABORTED') {
      ElMessage.error('请求超时,请检查网络')
    } else {
      ElMessage.error(backendMsg || error.message || 'Network error')
    }
    return Promise.reject(error)
  }
)

/**
 * 兼容:允许调用方传自定义 AxiosRequestConfig。
 * 项目里现有代码 request({ url, method, params }) 的形式继续可用。
 */
export type Config = AxiosRequestConfig

export default request

/**
 * 通用 WebSocket 管理器
 *
 * 设计目标：
 * - 自动鉴权：连接时自动把 localStorage 中的 JWT 作为 query 拼到 URL（?token=xxx）
 * - 多通道复用：一个类实例代表一条连接，exam / notification 各自实例化即可
 * - 自动重连：断线后按指数退避重连（1s, 2s, 4s ... 上限 30s）
 * - 心跳保活：默认每 30s 发送一次 { type: 'ping' }，pong 超时则判定连接死亡并重连
 * - 事件总线：基于消息体的 type 字段分发，同时暴露 open/close/error/message 等生命周期事件
 * - 干净退出：disconnect() 会停止心跳、取消重连、关闭 socket，供组件 onBeforeUnmount 调用
 *
 * 后端协议见 README；本类只负责传输层，业务语义由各 composable 解释。
 */

/** 事件回调：payload 取决于事件类型 */
export type WsEventHandler = (payload: any) => void

export interface WSOptions {
  /** 连接路径，例如 /ws/exam/123 或 /ws/notifications */
  path: string
  /** JWT token；未传则从 localStorage.token 读取 */
  token?: string
  /** 是否启用自动重连，默认 true */
  autoReconnect?: boolean
  /** 最大重连次数，默认 Infinity */
  maxReconnects?: number
  /** 心跳间隔（ms），默认 30000 */
  heartbeatInterval?: number
  /** 发出 ping 后等待 pong 的超时（ms），超时则强制重连，默认 10000 */
  pongTimeout?: number
  /** 心跳消息体，默认 { type: 'ping' } */
  heartbeatMessage?: object
  /** WebSocket 子协议 */
  protocols?: string | string[]
}

/** 内部归一化后的配置 */
interface NormalizedOptions {
  path: string
  token: string
  autoReconnect: boolean
  maxReconnects: number
  heartbeatInterval: number
  pongTimeout: number
  heartbeatMessage: object
  protocols: string | string[] | undefined
}

/** 生命周期 / 业务事件类型 */
export type WsEventType =
  | 'open'
  | 'close'
  | 'error'
  | 'message'
  | 'reconnect'
  | 'reconnecting'
  | string

/**
 * 从 Vite 环境变量或默认值推导 WebSocket 基地址。
 * 优先级：VITE_WS_BASE_URL > 生产环境按当前页面推导 > ws://localhost:9001
 */
export function getWsBaseUrl(): string {
  const fromEnv = import.meta.env.VITE_WS_BASE_URL
  if (fromEnv) return fromEnv.replace(/\/$/, '')
  // 生产环境按当前页面协议/host 推导 wss/ws
  if (import.meta.env.PROD && typeof window !== 'undefined' && window.location) {
    const proto = window.location.protocol === 'https:' ? 'wss:' : 'ws:'
    return `${proto}//${window.location.host}`
  }
  return 'ws://localhost:9001'
}

export class WebSocketManager {
  private ws: WebSocket | null = null
  private readonly opts: NormalizedOptions
  private readonly handlers = new Map<string, Set<WsEventHandler>>()

  private reconnectAttempts = 0
  private reconnectTimer: number | null = null
  private heartbeatTimer: number | null = null
  private pongTimer: number | null = null
  private waitingPong = false
  private manualClose = false

  constructor(options: WSOptions) {
    const token = options.token ?? localStorage.getItem('token') ?? ''
    this.opts = {
      path: options.path,
      token,
      autoReconnect: options.autoReconnect ?? true,
      maxReconnects: options.maxReconnects ?? Infinity,
      heartbeatInterval: options.heartbeatInterval ?? 30_000,
      pongTimeout: options.pongTimeout ?? 10_000,
      heartbeatMessage: options.heartbeatMessage ?? { type: 'ping' },
      protocols: options.protocols,
    }
  }

  /** 当前连接路径（只读） */
  get path(): string {
    return this.opts.path
  }

  /** 底层 readyState；未创建时返回 CLOSED(3) */
  get readyState(): number {
    return this.ws?.readyState ?? WebSocket.CLOSED
  }

  /** 是否处于 OPEN 状态 */
  get isConnected(): boolean {
    return this.ws?.readyState === WebSocket.OPEN
  }

  /** 是否处于 OPEN 状态（语义化别名） */
  get isOpen(): boolean {
    return this.isConnected
  }

  /**
   * 建立连接。若当前已连接或正在连接则直接返回。
   * 失败会触发 error 事件，并在启用自动重连时按指数退避重试。
   */
  connect(): void {
    if (
      this.ws &&
      (this.ws.readyState === WebSocket.OPEN ||
        this.ws.readyState === WebSocket.CONNECTING)
    ) {
      return
    }
    this.manualClose = false

    const base = getWsBaseUrl()
    const rawPath = this.opts.path
    const path = rawPath.startsWith('/') ? rawPath : `/${rawPath}`
    const token = this.opts.token || localStorage.getItem('token') || ''

    const query: string[] = []
    if (token) query.push(`token=${encodeURIComponent(token)}`)
    const qs = query.length ? `${path.includes('?') ? '&' : '?'}${query.join('&')}` : ''
    const url = `${base}${path}${qs}`

    try {
      this.ws = this.opts.protocols
        ? new WebSocket(url, this.opts.protocols)
        : new WebSocket(url)
    } catch (e) {
      this.emit('error', e)
      this.scheduleReconnect()
      return
    }

    this.ws.onopen = () => {
      this.reconnectAttempts = 0
      this.startHeartbeat()
      this.emit('open', { url })
    }

    this.ws.onmessage = (ev: MessageEvent) => {
      let data: any = ev.data
      if (typeof data === 'string') {
        try {
          data = JSON.parse(data)
        } catch {
          /* 非 JSON 文本，原样下发 */
        }
      }
      this.emit('message', data)
      if (data && typeof data === 'object' && typeof data.type === 'string') {
        if (data.type === 'pong') {
          this.handlePong()
        }
        this.emit(data.type, data)
      }
    }

    this.ws.onerror = (ev: Event) => {
      this.emit('error', ev)
    }

    this.ws.onclose = (ev: CloseEvent) => {
      this.stopHeartbeat()
      this.ws = null
      this.emit('close', ev)
      this.scheduleReconnect()
    }
  }

  /**
   * 主动断开。停止心跳、取消重连、关闭 socket。
   * 调用后不会再自动重连。
   */
  disconnect(code: number = 1000, reason?: string): void {
    this.manualClose = true
    this.stopHeartbeat()
    if (this.reconnectTimer !== null) {
      clearTimeout(this.reconnectTimer)
      this.reconnectTimer = null
    }
    this.reconnectAttempts = 0
    if (this.ws) {
      try {
        this.ws.close(code, reason)
      } catch {
        /* ignore */
      }
      this.ws = null
    }
    this.emit('close', { code, reason, manual: true })
  }

  /**
   * 发送消息。非字符串会自动 JSON.stringify。
   * @returns 是否成功投递（仅当处于 OPEN 状态时为 true）
   */
  send(data: unknown): boolean {
    if (!this.ws || this.ws.readyState !== WebSocket.OPEN) return false
    try {
      this.ws.send(typeof data === 'string' ? data : JSON.stringify(data))
      return true
    } catch (e) {
      this.emit('error', e)
      return false
    }
  }

  /* ---------------- 事件总线 ---------------- */

  /** 注册事件回调，返回取消注册函数 */
  on(type: WsEventType, handler: WsEventHandler): () => void {
    let set = this.handlers.get(type)
    if (!set) {
      set = new Set()
      this.handlers.set(type, set)
    }
    set.add(handler)
    return () => this.off(type, handler)
  }

  /** 注册一次性事件回调 */
  once(type: WsEventType, handler: WsEventHandler): () => void {
    const wrap: WsEventHandler = (payload) => {
      this.off(type, wrap)
      handler(payload)
    }
    return this.on(type, wrap)
  }

  /** 取消注册；不传 handler 则清空该事件全部回调 */
  off(type: WsEventType, handler?: WsEventHandler): void {
    if (!handler) {
      this.handlers.delete(type)
      return
    }
    this.handlers.get(type)?.delete(handler)
  }

  /** 移除所有事件回调（一般仅用于销毁） */
  removeAllListeners(): void {
    this.handlers.clear()
  }

  private emit(type: string, payload?: any): void {
    const set = this.handlers.get(type)
    if (!set || set.size === 0) return
    set.forEach((h) => {
      try {
        h(payload)
      } catch (e) {
        // 不让单个回调异常打断其他回调
        console.error('[WebSocketManager] handler error:', e)
      }
    })
  }

  /* ---------------- 心跳 ---------------- */

  private startHeartbeat(): void {
    this.stopHeartbeat()
    this.heartbeatTimer = window.setInterval(() => {
      // 发送 ping；若上一轮 pong 还没回来且已超时，则由 pongTimer 兜底重连
      this.send(this.opts.heartbeatMessage)
      this.waitingPong = true
      if (this.pongTimer !== null) clearTimeout(this.pongTimer)
      this.pongTimer = window.setTimeout(() => {
        if (this.waitingPong) {
          this.forceReconnect('pong timeout')
        }
      }, this.opts.pongTimeout)
    }, this.opts.heartbeatInterval)
  }

  private stopHeartbeat(): void {
    if (this.heartbeatTimer !== null) {
      clearInterval(this.heartbeatTimer)
      this.heartbeatTimer = null
    }
    if (this.pongTimer !== null) {
      clearTimeout(this.pongTimer)
      this.pongTimer = null
    }
    this.waitingPong = false
  }

  private handlePong(): void {
    this.waitingPong = false
    if (this.pongTimer !== null) {
      clearTimeout(this.pongTimer)
      this.pongTimer = null
    }
  }

  /* ---------------- 重连 ---------------- */

  /** 主动触发一次重连（关闭当前 socket，由 onclose 接力 scheduleReconnect） */
  private forceReconnect(reason: string): void {
    this.emit('reconnect', { reason })
    try {
      this.ws?.close()
    } catch {
      /* ignore */
    }
  }

  private scheduleReconnect(): void {
    if (!this.opts.autoReconnect || this.manualClose) return
    if (this.reconnectAttempts >= this.opts.maxReconnects) {
      this.emit('error', { message: 'max reconnects reached' })
      return
    }
    const attempt = this.reconnectAttempts++
    // 指数退避：1s, 2s, 4s, 8s, 16s, 30s, 30s ...
    const delay = Math.min(1000 * 2 ** attempt, 30_000)
    if (this.reconnectTimer !== null) clearTimeout(this.reconnectTimer)
    this.reconnectTimer = window.setTimeout(() => {
      this.emit('reconnecting', { attempt: attempt + 1, delay })
      this.connect()
    }, delay)
  }
}

/* ============================================================ *
 *  多通道注册表
 *  exam / notification 等各自一条连接，按 name 复用单例。
 * ============================================================ */

const channels = new Map<string, WebSocketManager>()

/**
 * 获取（或创建）具名通道。
 * 若同名通道已存在但 path 变了，会先关闭旧通道再新建，避免连到错误地址。
 */
export function getChannel(name: string, options: WSOptions): WebSocketManager {
  const existing = channels.get(name)
  if (existing) {
    if (existing.path !== options.path) {
      existing.disconnect()
      const mgr = new WebSocketManager(options)
      channels.set(name, mgr)
      return mgr
    }
    return existing
  }
  const mgr = new WebSocketManager(options)
  channels.set(name, mgr)
  return mgr
}

/** 关闭并移除具名通道 */
export function closeChannel(name: string): void {
  const ch = channels.get(name)
  if (ch) {
    ch.disconnect()
    ch.removeAllListeners()
    channels.delete(name)
  }
}

/** 关闭全部通道（一般在全局登出时调用） */
export function closeAllChannels(): void {
  channels.forEach((ch) => {
    ch.disconnect()
    ch.removeAllListeners()
  })
  channels.clear()
}

export default WebSocketManager
